exercises.tests:
def test_sign_negative():
    assert sign == "negative", f"ожидалось 'negative' для number=-7, получено {sign!r}"


def test_sign_is_str():
    assert isinstance(sign, str), "sign должен быть строкой"

def test_category_4xx():
    assert category == "4xx client error", f"ожидалось '4xx client error', получено {category}"


def test_is_success_ternary():
    assert is_success is False, "404 не входит в диапазон 2xx, ожидается False"

def test_verdict_slow():
    assert verdict == "SLOW", f"status_code == 200, но response_time_ms (1500) > sla_ms (1000), ожидалось 'SLOW', получено {verdict!r}"


def test_verdict_is_str():
    assert isinstance(verdict, str), "verdict должен быть строкой"

def test_wrong_check_is_false():
    assert wrong_check is False, "bool(0) — falsy, wrong_check должен быть False"


def test_correct_check_is_false():
    assert correct_check is False, "0 > 0 — False, correct_check должен быть False"


def test_both_are_bool():
    assert isinstance(wrong_check, bool) and isinstance(correct_check, bool), "оба значения должны быть именно bool"
